/*
* Creates a mocked react router.  Pass in an object with any functions or attributes
* you wish to stub or spy yourself, defaults to no-op functions and an empty location.
* */
export default function createMockRouter(mockRouter) {
  return Object.assign({}, {
    createHref: Function.prototype,
    push: Function.prototype,
    replace: Function.prototype,
    go: Function.prototype,
    goBack: Function.prototype,
    goForward: Function.prototype,
    setLeaveHook: Function.prototype,
    setRouteLeaveHook: Function.prototype,
    isActive: Function.prototype,
    location: {
      query: {},
      search: '',
    },
  },
  mockRouter);
}
